    (2, "装饰器雏形：日志包装。", "def logger(func):\n    def wrapper(*args):\n        print(\"Calling\")\n        return func(*args)\n    return wrapper\n\n@logger\ndef add(a, b):\n    return a + b\n\nprint(add(2, 3))", "填空装饰器。", "def logger(func):\n    def wrapper(*args):\n        print(\"Calling\")\n        return func(*args)\n    return wrapper\n\n@logger\ndef add(a, b):\n    return a + b\n\nprint(add(2, 3))"),
