    (4, "闭包实现函数记忆化。", "def memoize(func):\n    cache = {}\n    def wrapper(n):\n        if n not in cache:\n            cache[n] = func(n)\n        return cache[n]\n    return wrapper\n\n@memoize\ndef fib(n):\n    if n <= 1:\n        return n\n    return fib(n - 1) + fib(n - 2)\n\nprint(fib(10))", "填空记忆化。", "def memoize(func):\n    cache = {}\n    def wrapper(n):\n        if n not in cache:\n            cache[n] = func(n)\n        return cache[n]\n    return wrapper\n\n@memoize\ndef fib(n):\n    if n <= 1:\n        return n\n    return fib(n - 1) + fib(n - 2)\n\nprint(fib(10))"),
    (5, "nonlocal 实现状态机。", "def make_state():\n    state = {\"count\": 0}\n    def transition(action):\n        nonlocal state\n        if action == \"inc\":\n            state[\"count\"] += 1\n        elif action == \"reset\":\n            state[\"count\"] = 0\n        return state[\"count\"]\n    return transition\n\nsm = make_state()\nprint(sm(\"inc\"))\nprint(sm(\"inc\"))\nprint(sm(\"reset\"))", "填空状态机。", "def make_state():\n    state = {\"count\": 0}\n    def transition(action):\n        nonlocal state\n        if action == \"inc\":\n            state[\"count\"] += 1\n        elif action == \"reset\":\n            state[\"count\"] = 0\n        return state[\"count\"]\n    return transition\n\nsm = make_state()\nprint(sm(\"inc\"))\nprint(sm(\"inc\"))\nprint(sm(\"reset\"))"),
